INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tamatebako_math', '表の空欄推測', '来店客数（人）と販売数（個）（比例）', '次の表は、来店客数（人）と販売数（個）の関係を示したものである。表の空欄に当てはまる数値として最も近いものを1つ選びなさい。', '[{"headers": ["", "店舗1", "店舗2", "店舗3", "店舗4"], "rows": [["来店客数（人）", "29", "64", "85", "87"], ["販売数（個）", "145", "320", "425", "？"]]}]', '["565個", "435個", "384個", "474個", "503個"]', 1, '["販売数（個）÷来店客数（人）＝5（一定）。店舗4の来店客数（人）は87なので、販売数（個）は435個と推測できる。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（表の空欄推測 Part2、全30問）を基に作成。選択肢の順序はシャッフルして登録。', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tamatebako_math', '表の空欄推測', '走行距離（km）と燃料消費量（L）（比例）', '次の表は、走行距離（km）と燃料消費量（L）の関係を示したものである。表の空欄に当てはまる数値として最も近いものを1つ選びなさい。', '[{"headers": ["", "車両1", "車両2", "車両3", "車両4"], "rows": [["走行距離（km）", "99", "253", "286", "319"], ["燃料消費量（L）", "9", "23", "26", "？"]]}]', '["33L", "23L", "20L", "29L", "37L"]', 3, '["走行距離（km）÷燃料消費量（L）＝11（一定）。車両4の走行距離（km）は319なので、燃料消費量（L）は29Lと推測できる。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（表の空欄推測 Part2、全30問）を基に作成。選択肢の順序はシャッフルして登録。', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tamatebako_math', '表の空欄推測', '印刷ページ数（枚）とインク使用量（ml）（比例）', '次の表は、印刷ページ数（枚）とインク使用量（ml）の関係を示したものである。表の空欄に当てはまる数値として最も近いものを1つ選びなさい。', '[{"headers": ["", "案件1", "案件2", "案件3", "案件4"], "rows": [["印刷ページ数（枚）", "131", "199", "388", "496"], ["インク使用量（ml）", "393", "597", "1,164", "？"]]}]', '["1,330ml", "1,788ml", "1,671ml", "1,488ml", "1,141ml"]', 3, '["インク使用量（ml）÷印刷ページ数（枚）＝3（一定）。案件4の印刷ページ数（枚）は496なので、インク使用量（ml）は1,488mlと推測できる。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（表の空欄推測 Part2、全30問）を基に作成。選択肢の順序はシャッフルして登録。', NULL);
