INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tamatebako_math', '表の空欄推測', 'バニラ（個）とチョコ（個）と抹茶（個）と売上合計（円）（連立方程式）', 'アイスクリーム店で今週の平日の売り上げを調べている。金曜日の売上合計はいくらと推測できるか。表の空欄に当てはまる数値として最も近いものを1つ選びなさい。', '[{"headers": ["", "月曜日", "火曜日", "水曜日", "木曜日", "金曜日"], "rows": [["バニラ（個）", "32", "73", "16", "97", "45"], ["チョコ（個）", "21", "116", "52", "116", "105"], ["抹茶（個）", "95", "90", "80", "39", "113"], ["売上合計（円）", "97,770", "132,860", "77,320", "111,860", "？"]]}]', '["128,630円", "103,352円", "117,349円", "139,051円", "147,609円"]', 0, '["バニラの単価をx、チョコをy、抹茶をzとして、月・火・水の3日分から連立方程式を立てる。<br>　月：32x＋21y＋95z＝97,770<br>　火：73x＋116y＋90z＝132,860<br>　水：16x＋52y＋80z＝77,320<br>この連立方程式をクラメルの公式（行列式）で解くと、係数の行列式D＝239,100、xの行列式Dx＝176,934,000より x＝Dx÷D＝740円。同様にy＝90円、z＝760円と求まる。<br>金曜日：45×740＋105×90＋113×760＝128,630円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（表の空欄推測 Part2、全30問）を基に作成。選択肢の順序はシャッフルして登録。', NULL);
