INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tamatebako_math', '表の空欄推測', '距離（km）と段ボール箱数（箱）と料金（円）（順位補間）', '次の表は、6件の引っ越しの距離・段ボール箱数と、引っ越し料金の関係を表にしたものです。Fはいくらと推測できるか。表の空欄に当てはまる数値として最も近いものを1つ選びなさい。', '[{"headers": ["", "A", "B", "C", "D", "E", "F"], "rows": [["距離（km）", "89", "62", "57", "78", "68", "76"], ["段ボール箱数（箱）", "42", "18", "12", "32", "25", "31"], ["料金（円）", "26,000", "15,000", "9,000", "26,000", "15,000", "？"]]}]', '["19,043円", "21,310円", "26,000円", "30,666円", "22,968円"]', 2, '["距離（km）・段ボール箱数（箱）のどちらで順位付けしても、FはD（78／32）に近い側に位置する（距離（km）順：C<B<E<F<D<A、段ボール箱数（箱）順：C<B<E<F<D<A）。D＝26,000円のグループに含まれると推測でき、答えは26,000円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（表の空欄推測 Part2、全30問）を基に作成。選択肢の順序はシャッフルして登録。', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tamatebako_math', '表の空欄推測', 'ページ数（p）と部数（部）と料金（円）（順位補間）', '次の表は、6件の印刷案件のページ数・部数と、印刷料金の関係を表にしたものです。Fはいくらと推測できるか。表の空欄に当てはまる数値として最も近いものを1つ選びなさい。', '[{"headers": ["", "A", "B", "C", "D", "E", "F"], "rows": [["ページ数（p）", "61", "37", "32", "55", "46", "54"], ["部数（部）", "114", "82", "78", "102", "89", "100"], ["料金（円）", "41,000", "20,000", "16,000", "41,000", "20,000", "？"]]}]', '["33,740円", "41,000円", "52,434円", "45,135円", "29,435円"]', 1, '["ページ数（p）・部数（部）のどちらで順位付けしても、FはD（55／102）に近い側に位置する（ページ数（p）順：C<B<E<F<D<A、部数（部）順：C<B<E<F<D<A）。D＝41,000円のグループに含まれると推測でき、答えは41,000円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（表の空欄推測 Part2、全30問）を基に作成。選択肢の順序はシャッフルして登録。', NULL);
