INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tamatebako_math', '表の空欄推測', '床面積（㎡）と部屋数（部屋）と料金（円）（順位補間）', '次の表は、6件の清掃案件の床面積・部屋数と、清掃料金の関係を表にしたものです。Fはいくらと推測できるか。表の空欄に当てはまる数値として最も近いものを1つ選びなさい。', '[{"headers": ["", "A", "B", "C", "D", "E", "F"], "rows": [["床面積（㎡）", "106", "79", "75", "95", "88", "93"], ["部屋数（部屋）", "38", "8", "3", "26", "17", "23"], ["料金（円）", "48,000", "25,000", "20,000", "48,000", "25,000", "？"]]}]', '["38,031円", "48,000円", "59,960円", "57,038円", "41,075円"]', 1, '["床面積（㎡）・部屋数（部屋）のどちらで順位付けしても、FはD（95／26）に近い側に位置する（床面積（㎡）順：C<B<E<F<D<A、部屋数（部屋）順：C<B<E<F<D<A）。D＝48,000円のグループに含まれると推測でき、答えは48,000円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（表の空欄推測 Part2、全30問）を基に作成。選択肢の順序はシャッフルして登録。', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tamatebako_math', '表の空欄推測', '撮影枚数（枚）と拘束時間（時間）と料金（円）（順位補間）', '次の表は、6件の撮影案件の撮影枚数・拘束時間と、撮影料金の関係を表にしたものです。Fはいくらと推測できるか。表の空欄に当てはまる数値として最も近いものを1つ選びなさい。', '[{"headers": ["", "A", "B", "C", "D", "E", "F"], "rows": [["撮影枚数（枚）", "69", "38", "33", "59", "45", "58"], ["拘束時間（時間）", "28", "7", "1", "22", "13", "19"], ["料金（円）", "34,000", "19,000", "17,000", "34,000", "19,000", "？"]]}]', '["41,724円", "29,995円", "38,969円", "34,000円", "25,878円"]', 3, '["撮影枚数（枚）・拘束時間（時間）のどちらで順位付けしても、FはD（59／22）に近い側に位置する（撮影枚数（枚）順：C<B<E<F<D<A、拘束時間（時間）順：C<B<E<F<D<A）。D＝34,000円のグループに含まれると推測でき、答えは34,000円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（表の空欄推測 Part2、全30問）を基に作成。選択肢の順序はシャッフルして登録。', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tamatebako_math', '表の空欄推測', '重量（kg）と個口数（個）と料金（円）（順位補間）', '次の表は、6件の運送案件の重量・個口数と、運送料金の関係を表にしたものです。Fはいくらと推測できるか。表の空欄に当てはまる数値として最も近いものを1つ選びなさい。', '[{"headers": ["", "A", "B", "C", "D", "E", "F"], "rows": [["重量（kg）", "46", "15", "9", "34", "22", "23"], ["個口数（個）", "34", "11", "3", "27", "16", "17"], ["料金（円）", "42,000", "20,000", "17,000", "42,000", "20,000", "？"]]}]', '["25,715円", "23,243円", "17,275円", "14,172円", "20,000円"]', 4, '["重量（kg）・個口数（個）のどちらで順位付けしても、FはE（22／16）に近い側に位置する（重量（kg）順：C<B<E<F<D<A、個口数（個）順：C<B<E<F<D<A）。E＝20,000円のグループに含まれると推測でき、答えは20,000円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（表の空欄推測 Part2、全30問）を基に作成。選択肢の順序はシャッフルして登録。', NULL);
